import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './range-slider.module.scss'

export interface RangeSliderProps {
  value?: [number, number]
  defaultValue?: [number, number]
  onChange?: (value: [number, number]) => void
  min?: number
  max?: number
  step?: number
  label?: string
  disabled?: boolean
  className?: string
}

/** Dual-thumb range input for price, radius and numeric intervals. */
export function RangeSlider({
  value: valueProp,
  defaultValue = [20, 80],
  onChange,
  min = 0,
  max = 100,
  step = 1,
  label = 'Range',
  disabled = false,
  className,
}: RangeSliderProps) {
  const [uncontrolled, setUncontrolled] = React.useState<[number, number]>(
    defaultValue,
  )
  const value = valueProp ?? uncontrolled
  const [low, high] = value

  const update = (nextLow: number, nextHigh: number) => {
    if (valueProp === undefined) setUncontrolled([nextLow, nextHigh])
    onChange?.([nextLow, nextHigh])
  }

  const percent = (current: number) => ((current - min) / (max - min)) * 100

  return (
    <div className={cx(styles.root, className)}>
      <div className={styles.header}>
        <span>{label}</span>
        <span className={styles.value}>
          {low} – {high}
        </span>
      </div>
      <div className={styles.track}>
        <span className={styles.rail} aria-hidden />
        <span
          className={styles.fill}
          style={{ left: `${percent(low)}%`, right: `${100 - percent(high)}%` }}
          aria-hidden
        />
        <input
          type="range"
          aria-label={`${label} minimum`}
          min={min}
          max={max}
          step={step}
          value={low}
          disabled={disabled}
          className={styles.input}
          onChange={(event) =>
            update(Math.min(Number(event.currentTarget.value), high), high)
          }
        />
        <input
          type="range"
          aria-label={`${label} maximum`}
          min={min}
          max={max}
          step={step}
          value={high}
          disabled={disabled}
          className={styles.input}
          onChange={(event) =>
            update(low, Math.max(Number(event.currentTarget.value), low))
          }
        />
      </div>
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: vz.space(2);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(3);
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
}

.value {
  color: vz.color('muted-foreground');
  font-variant-numeric: tabular-nums;
}

.track {
  position: relative;
  height: vz.space(5);
}

.rail {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 4px;
  border-radius: vz.radius('full');
  background: vz.color('muted');
  transform: translateY(-50%);
}

.fill {
  position: absolute;
  top: 50%;
  height: 4px;
  border-radius: vz.radius('full');
  background: vz.color('primary');
  transform: translateY(-50%);
}

.input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  appearance: none;
  background: transparent;
  pointer-events: none;

  &::-webkit-slider-thumb {
    appearance: none;
    width: 1rem;
    height: 1rem;
    border: 2px solid vz.color('primary');
    border-radius: vz.radius('full');
    background: vz.color('card');
    box-shadow: vz.elevation(1);
    pointer-events: auto;
    cursor: grab;
    transition: transform vz.duration('fast') vz.ease('out');
  }

  &::-moz-range-thumb {
    width: 1rem;
    height: 1rem;
    border: 2px solid vz.color('primary');
    border-radius: vz.radius('full');
    background: vz.color('card');
    box-shadow: vz.elevation(1);
    pointer-events: auto;
    cursor: grab;
  }

  &:focus-visible {
    outline: none;

    &::-webkit-slider-thumb {
      outline: 2px solid vz.color('ring', 0.6);
      outline-offset: 2px;
    }
  }

  @include vz.motion-reduce {
    &::-webkit-slider-thumb {
      transition: none;
    }
  }
}
